class Solution {
public:
    char repeatedCharacter(std::string s) {
        int mask = 0;
        for (char ch : s) {
            int bit = 1 << (ch - 'a');
            if (mask & bit) return ch;
            mask |= bit;
        }
        return ' ';
    }
};

class Solution {
    public char repeatedCharacter(String s) {
        int mask = 0;
        for (int i = 0; i < s.length(); ++i) {
            char ch = s.charAt(i);
            int bit = 1 << (ch - 'a');
            if ((mask & bit) != 0) return ch;
            mask |= bit;
        }
        return ' ';
    }
}

var repeatedCharacter = function(s) {
    let mask = 0;
    for (let i = 0; i < s.length; ++i) {
        const bit = 1 << (s.charCodeAt(i) - 97);
        if ((mask & bit) !== 0) return s[i];
        mask |= bit;
    }
    return '';
};
